CREATE SCHEMA IF NOT EXISTS koa_private;
GRANT USAGE ON SCHEMA koa_private TO anon,authenticated,service_role;
ALTER FUNCTION public.reader_blocked(uuid,uuid) SET SCHEMA koa_private;
ALTER FUNCTION public.reader_club_member(uuid,uuid) SET SCHEMA koa_private;
DO $$DECLARE r record; d text;BEGIN FOR r IN SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','koa_private') AND p.prokind='f' LOOP d:=pg_get_functiondef(r.oid);IF d LIKE '%public.reader_blocked(%' OR d LIKE '%public.reader_club_member(%' THEN EXECUTE replace(replace(d,'public.reader_blocked(','koa_private.reader_blocked('),'public.reader_club_member(','koa_private.reader_club_member(');END IF;END LOOP;END$$;
CREATE FUNCTION public.reader_blocked(a uuid,b uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$BEGIN IF auth.uid() IS NULL OR (a IS DISTINCT FROM auth.uid() AND b IS DISTINCT FROM auth.uid()) THEN RAISE EXCEPTION 'No puedes consultar relaciones ajenas.';END IF;RETURN koa_private.reader_blocked(a,b);END$$;
CREATE FUNCTION public.reader_club_member(c uuid,u uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$BEGIN IF auth.uid() IS NULL OR u IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'No puedes consultar relaciones ajenas.';END IF;RETURN koa_private.reader_club_member(c,u);END$$;
REVOKE ALL ON FUNCTION public.reader_blocked(uuid,uuid),public.reader_club_member(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.reader_blocked(uuid,uuid),public.reader_club_member(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.reader_joint_percent(p_reading uuid,p_user uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT CASE WHEN EXISTS(SELECT 1 FROM public.completed_readings c WHERE c.book_id=b.id AND c.cycle=b.reading_cycle AND c.streak_day IS NOT NULL) THEN 100 WHEN b.pages>0 THEN least(100,greatest(0,(b.current_page::numeric*100/b.pages)::integer)) ELSE 0 END FROM public.reader_joint_participants p JOIN public.reader_joint_readings r ON r.id=p.reading_id JOIN public.books b ON b.id=p.book_id AND b.user_id=p.user_id WHERE p.reading_id=p_reading AND p.user_id=p_user AND p.left_at IS NULL AND koa_private.reader_club_member(r.club_id,auth.uid()) AND koa_private.reader_club_member(r.club_id,p.user_id) AND NOT koa_private.reader_blocked(p.user_id,auth.uid())$$;